  "inlineSchema": "// Prisma Schema for Textil L&M Backend System\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ==========================================\n// MODELS\n// ==========================================\n\nmodel RoleDefinition {\n  id          String   @id @default(uuid())\n  code        String   @unique\n  name        String\n  description String\n  permissions String[]\n  isSystem    Boolean  @default(false) @map(\"is_system\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  users User[]\n\n  @@map(\"roles\")\n}\n\nmodel User {\n  id             String          @id @default(uuid())\n  workerId       String?         @unique @map(\"worker_id\")\n  documentType   String          @default(\"DNI\") @map(\"document_type\")\n  documentNumber String?         @map(\"document_number\")\n  email          String          @unique\n  passwordHash   String          @map(\"password_hash\")\n  firstName      String          @map(\"first_name\")\n  lastName       String          @map(\"last_name\")\n  role           String          @default(\"ADMINISTRADOR\")\n  roleDefinition RoleDefinition? @relation(fields: [role], references: [code], onDelete: Restrict, onUpdate: Cascade)\n  status         String          @default(\"ACTIVE\") // ACTIVE, INACTIVE, SUSPENDED\n  phone          String?\n  jobTitle       String?         @map(\"job_title\")\n  avatarUrl      String?         @map(\"avatar_url\")\n  lastLoginAt    DateTime?       @map(\"last_login_at\")\n  createdAt      DateTime        @default(now()) @map(\"created_at\")\n  updatedAt      DateTime        @updatedAt @map(\"updated_at\")\n\n  startedRolls    ProductionRoll[] @relation(\"RollStartOperator\")\n  endedRolls      ProductionRoll[] @relation(\"RollEndOperator\")\n  batchStatusLogs BatchStatusLog[]\n\n  @@map(\"users\")\n}\n\nmodel Machine {\n  id           String   @id @default(uuid())\n  code         String   @unique\n  name         String\n  type         String   @default(\"Costura\")\n  brand        String?\n  model        String?\n  serialNumber String?  @map(\"serial_number\")\n  status       String   @default(\"OPERATIVE\") // OPERATIVE, MAINTENANCE, OUT_OF_SERVICE\n  designTypes  String[] @default([]) @map(\"design_types\") // Dray, Win, etc.\n  location     String?\n  notes        String?\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  productionBatches ProductionBatch[]\n\n  @@map(\"machines\")\n}\n\nmodel Supplier {\n  id        String   @id @default(uuid())\n  document  String   @unique // RUC / DNI\n  name      String // Razón Social\n  phone     String?\n  email     String?\n  address   String?\n  yarnTypes String[] @default([]) @map(\"yarn_types\") // Lista de tipos de hilo suministrados\n  status    String   @default(\"ACTIVE\") // ACTIVE, INACTIVE\n  notes     String?\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  productionBatches ProductionBatch[]\n\n  @@map(\"suppliers\")\n}\n\nmodel ProductionBatch {\n  id           String    @id @default(uuid())\n  batchNumber  String    @unique @map(\"batch_number\")\n  trackingCode String?   @unique @map(\"tracking_code\")\n  machineId    String    @map(\"machine_id\")\n  machine      Machine   @relation(fields: [machineId], references: [id], onDelete: Restrict)\n  machineCode  String?   @map(\"machine_code\")\n  machineName  String?   @map(\"machine_name\")\n  supplierId   String    @map(\"supplier_id\")\n  supplier     Supplier  @relation(fields: [supplierId], references: [id], onDelete: Restrict)\n  supplierName String?   @map(\"supplier_name\")\n  startDate    DateTime  @default(now()) @map(\"start_date\")\n  endDate      DateTime? @map(\"end_date\")\n  status       String    @default(\"REQUESTED\") // REQUESTED, IN_PROGRESS, PAUSED, COMPLETED\n  notes        String?\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n\n  yarns      BatchYarn[]\n  rolls      ProductionRoll[]\n  statusLogs BatchStatusLog[]\n\n  @@map(\"production_batches\")\n}\n\nmodel BatchStatusLog {\n  id              String          @id @default(uuid())\n  batchId         String          @map(\"batch_id\")\n  batch           ProductionBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  status          String\n  changedByUserId String?         @map(\"changed_by_user_id\")\n  changedByUser   User?           @relation(fields: [changedByUserId], references: [id], onDelete: SetNull)\n  notes           String?\n  createdAt       DateTime        @default(now()) @map(\"created_at\")\n\n  @@map(\"batch_status_logs\")\n}\n\nmodel BatchYarn {\n  id          String          @id @default(uuid())\n  batchId     String          @map(\"batch_id\")\n  batch       ProductionBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  yarnName    String          @map(\"yarn_name\")\n  color       String?\n  lotCode     String?         @map(\"lot_code\")\n  rollCount   Int?            @default(0) @map(\"roll_count\")\n  totalWeight Float?          @default(0) @map(\"total_weight\")\n  status      String          @default(\"IN_PREPARATION\")\n  notes       String?\n  createdAt   DateTime        @default(now()) @map(\"created_at\")\n  updatedAt   DateTime        @updatedAt @map(\"updated_at\")\n\n  rolls ProductionRoll[]\n\n  @@map(\"batch_yarns\")\n}\n\nmodel ProductionRoll {\n  id               String          @id @default(uuid())\n  batchId          String          @map(\"batch_id\")\n  batch            ProductionBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  yarnId           String?         @map(\"yarn_id\")\n  yarn             BatchYarn?      @relation(fields: [yarnId], references: [id], onDelete: SetNull)\n  yarnName         String?         @map(\"yarn_name\")\n  rollNumber       String          @map(\"roll_number\")\n  startDate        String          @map(\"start_date\")\n  startTime        String          @map(\"start_time\")\n  startOperatorId  String          @map(\"start_operator_id\")\n  startOperatorRel User            @relation(\"RollStartOperator\", fields: [startOperatorId], references: [id], onDelete: Restrict)\n  startOperator    String?         @map(\"start_operator\")\n  endDate          String?         @map(\"end_date\")\n  endTime          String?         @map(\"end_time\")\n  endOperatorId    String?         @map(\"end_operator_id\")\n  endOperatorRel   User?           @relation(\"RollEndOperator\", fields: [endOperatorId], references: [id], onDelete: SetNull)\n  endOperator      String?         @map(\"end_operator\")\n  weight           Float?\n  status           String          @default(\"REGISTERED\") // REGISTERED, IN_PREPARATION, READY_FOR_APPROVAL, READY_FOR_PICKUP, DELIVERED\n  observations     String?\n  createdAt        DateTime        @default(now()) @map(\"created_at\")\n  updatedAt        DateTime        @updatedAt @map(\"updated_at\")\n\n  @@unique([batchId, rollNumber], map: \"idx_rolls_batch_roll_number\")\n  @@map(\"production_rolls\")\n}\n",
